// Bangun data/jadwal.json dari baris berstatus "terverifikasi"
const rows = $input.all().map(r => r.json).filter(r => String(r.status).trim() === 'terverifikasi');
const seen = new Set();
const jadwal = rows.filter(r => r.tanggal && r.mulai && r.selesai && r.kelompok && !seen.has(r.kunci || r.id) && seen.add(r.kunci || r.id))
  .map(r => ({ id: String(r.id), ulp: r.ulp || 'Lambung Mangkurat', jenis: r.jenis || 'terjadwal', tanggal: String(r.tanggal), mulai: String(r.mulai).slice(0, 5), selesai: String(r.selesai).slice(0, 5),
    kelompok: String(r.kelompok).split(',').map(s => s.trim()).filter(Boolean),
    alasan: r.alasan || '', status: 'terverifikasi', poster: r.poster || undefined, sumber_url: r.sumber_url || undefined,
    sumber: 'Pengumuman resmi PLN ULP Lambung Mangkurat' }))
  .sort((a, b) => (a.tanggal + a.mulai).localeCompare(b.tanggal + b.mulai));
const doc = { diperbarui: new Date().toISOString(), unit: 'PLN UP3 Banjarmasin: ULP Lambung Mangkurat dan ULP Ahmad Yani',
  catatan: 'Setiap entri bersumber dari satu pengumuman resmi PLN dan diverifikasi manusia. Jam = estimasi waktu pada pengumuman.', jadwal };
return [{ json: { isi: JSON.stringify(doc, null, 1), jumlah: jadwal.length } }];
